START TRANSACTION;
INSERT INTO liqi_enterprise
  (enterprise_name, register_address, credit_code, short_name, insured_count,
   tenant_id, creator, updater, create_time, update_time, deleted, enrich_status)
SELECT t.enterprise_name, t.register_address, t.credit_code,
   LEFT(t.enterprise_name, 4), 0,
   1, 'excel-import-xlw', 'excel-import-xlw', NOW(), NOW(), b'0', 0
FROM liqi_xlw_stage t
WHERE NOT EXISTS (
  SELECT 1 FROM liqi_enterprise e WHERE e.credit_code = t.credit_code AND e.deleted = 0
);
SELECT ROW_COUNT() AS 本次新增行数;
COMMIT;
SELECT '导入后企业总数' AS k, COUNT(*) AS v FROM liqi_enterprise WHERE deleted=0;
SELECT creator AS 来源, COUNT(*) AS 数量 FROM liqi_enterprise WHERE deleted=0 GROUP BY creator;
SELECT '本次导入(enrich_status=0未回填)' AS k, COUNT(*) AS v FROM liqi_enterprise WHERE creator='excel-import-xlw' AND deleted=0;
SELECT id, enterprise_name, credit_code, short_name, tenant_id, enrich_status, LEFT(register_address,28) AS addr FROM liqi_enterprise WHERE creator='excel-import-xlw' LIMIT 5;
DROP TABLE liqi_xlw_stage;